build: fn(b: Build) -[Exec, FS]> {
    gen: b.add_executable("gen", ["Tools/Gen.jet"], [])
    #Impure("make the rows table with gen") {
        rows: b.run("rows", b.host(gen), ["FS"])  // gen built for this machine
        rows.input("rows.tsv")                     // declared and passed at once
        table: rows.output("Registry/Rows.jet")    // declared, passed, returned
        rows.timeout(2min)
        app: b.add_executable("app", ["run.jet", table.path()], [rows])
        b.default(app)
    }
}

build: fn(b: Build) -[Exec, FS]> {
    // each line finishes before the next one starts
    gen: b.compile("gen", ["Tools/Gen.jet"])
    b.exec([String]{gen, "rows.tsv", "Registry/Rows.jet"})
    app: b.add_executable("app", ["run.jet", "Registry/Rows.jet"], [])
    b.default(app)
}

// Tools/project/Build.jet: an ordinary Jet program
run: fn() {
    process.cmd([String]{"jet", "build", "--output-dir=out", "Gen"}).run() ?? fail("gen")
    process.cmd([String]{"out/gen", "rows.tsv", "Registry/Rows.jet"}).run() ?? fail("rows")
    process.cmd([String]{"jet", "build", "App"}).run() ?? fail("app")
}

