decisions.story:
A todo app shows a list that refreshes in every open tab when one tab adds an item. It remembers the last filter in browser storage. The program below is the user's code. It is the same under every option. Each option then shows the few lines of battery source that invalidate the live list and read storage, because those are the lines that change.

```jet
use web

todos: fn() -> [String] { [String]{"milk"} }

home: fn() -> WebPage { web.page("Todos", todos().join(", ")) }

run: fn() {
    web.app()
        .route("/", home)
        .serve()
}
```

options.code:
// Battery source, Jetpack/Provider/Batteries/web/web.jet.
use {
    app
    storage: core.browser.storage
}

// The live list refreshes in every tab: app owns the live store.
// invalidate names the source function behind the live list.
added: fn() { app.invalidate(todos) }

// The last filter, from browser storage.
last_filter: fn() -[Browser]> String { storage.local.get("filter") ?? "all" }

// Battery source, Jetpack/Provider/Batteries/web/web.jet.
// New: a battery may declare runtime bindings, as Core does.
#Import(c) priv live_publish: fn(topic: String, event: String) = "jet_web_live_publish"
#Import(c) priv local_get: fn(key: String) -> String? = "jet_web_storage_local_get"

// The battery owns the live store and publishes itself.
added: fn(source: String) { live_publish("live:{source}", "{{\"live\":\"invalidate\"}}") }

// The last filter, from browser storage.
last_filter: fn() -[Browser]> String { local_get("filter") ?? "all" }

// Battery source, Jetpack/Provider/Batteries/web/web.jet.
use {
    mem: core.mem
    server: core.http.server
}

// New public Core: the battery keeps its own live store and publishes.
added: fn(source: String) {
    _store: mem.process_shared(new_live_store)
    server.publish("live:{source}", "{{\"live\":\"invalidate\"}}")
}

// Browser storage is the battery's own process-wide map.
last_filter: fn() -[Browser]> String { mem.process_shared(new_storage).get("filter") ?? "all" }

// Battery source, Jetpack/Provider/Batteries/web/web.jet, today's shape.
use {
    core_web: core.web
    local: core.web.storage.local
}

// core.web still owns the live store and its private calls.
added: fn() { core_web.invalidate(todos) }

last_filter: fn() -[Browser]> String { local.get("filter") ?? "all" }

