    if task.version != version -> return Err(TaskError.Conflict(task))
    self.check_assignee(task.project, draft)
    saved: self.tasks.put(Task{id: task.id, project: task.project, title: draft.title.trim(), notes: draft.notes, status: task.status, assignee: draft.assignee, due: draft.due, version: task.version + 1})
    self.after_assign(saved, task.assignee)
    Ok(saved)
}
// The editor spins until the server answers.
// For an instant edit, the app drops after_assign here and adds a method
// the screen calls after the reply:
#App.SignedIn
tell_if_assigned: fn(self, id: TaskID, before: auth.AccountID?) -[DB.Read]> TaskError! { ... }

